// Check for degenerate case where v1 is zero vector
if (v1.LengthSquared() == 0) {
    // Handle degenerate case, e.g., set v2 and v3 to arbitrary orthonormal vectors
    *v2 = Vector3<T>(1, 0, 0);
    *v3 = Vector3<T>(0, 1, 0);
} else {
    // Normalize v1 to get the first vector of the coordinate system
    Vector3<T> n = v1.Normalize();

    // Choose a vector that is not parallel to n
    Vector3<T> a = (std::abs(n.x) > 0.5) ? Vector3<T>(0, 1, 0) : Vector3<T>(1, 0, 0);

    // Compute the cross product of n and a to get the second vector
    *v2 = n.Cross(a).Normalize();

    // Compute the cross product of n and v2 to get the third vector
    *v3 = n.Cross(*v2);
}

